args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?director ?directorLabel ?spouse ?spouseLabel WHERE {
  dbr:Apprentice_to_Murder dbo:director ?director .
  OPTIONAL { ?director (dbo:spouse|dbp:spouse) ?spouse . }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (langMatches(lang(?directorLabel), "EN")) }
  OPTIONAL { ?spouse rdfs:label ?spouseLabel . FILTER (langMatches(lang(?spouseLabel), "EN")) }
}

